{"expected_revision_id": "2765ded9-d949-4a8c-b235-11c94af08ab3", "source": "module enable_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    output reg  [3:0] q
);

    always @(posedge clk) begin
        if (rst)
            q <= 4'd0;
        else if (en)
            q <= q + 4'd1;
    end

endmodule
"}
